function paintTeamPreviews(){for(const side of ['home','away']){
 const id=side==='home'?home:away,c=$(side+'Portrait');if(!c)continue;
 const ctx=c.getContext('2d'),team=kitFor(TEAMS[id],kitSelections[side==='home'?0:1]),r=roster(id),star=r[id===0?0:8]||r[0];
 const dot=$(side+'KitDot');if(dot){dot.style.background=team.primary;dot.style.borderColor=team.secondary;}
 const caption=$(side+'KitCaption');if(caption)caption.textContent=(side==='home'?'HOME • ATTACK →':'← ATTACK • AWAY')+' · '+team.kitLabel+' KIT';
 ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#13364b';ctx.fillRect(0,0,c.width,c.height);
 const glow=ctx.createRadialGradient(90,85,5,90,85,120);glow.addColorStop(0,team.primary+'aa');glow.addColorStop(1,'#092739');ctx.fillStyle=glow;ctx.fillRect(0,0,c.width,c.height);
 ctx.save();ctx.translate(87,162);ctx.scale(1.45,1.45);
 renderer.drawPlayer(ctx,{...game.player(0,3),t:0,i:3,x:0,y:0,src:star,face:side==='home'?1:-1,dx:.5,dy:0,z:0,anim:performance.now()/1300,action:'idle',controlled:false}, {getTeam:()=>team,options:{showNames:false}});
 ctx.restore();
 ctx.save();ctx.translate(153,36);ctx.scale(.47,.47);renderer.drawTransformation(ctx,{...SHOTS[team.shot],id:team.shot},1.5);ctx.restore();
 }}
function start(){if(mode==='versus')humans=2;else humans=1;game.init({home,away,mode,humans,rosters:[mode==='career'&&career?career.roster.map(p=>({...p})):roster(home),roster(away)],lineups:[planFor(home).lineup.slice(),planFor(away).lineup.slice()],formations:[planFor(home).formation,planFor(away).formation],plans:[planFor(home),planFor(away)],options:{...opt,kitChoices:kitSelections.slice()}});if(preTalkChoices[0]!=='none')game.applyTeamTalk(0,preTalkChoices[0],'pregame');if(preTalkChoices[1]!=='none')game.applyTeamTalk(1,preTalkChoices[1],'pregame');if(mode==='pk')game.startPK(false);closeMenu();drawHUD()}
function drawHUD(){let p=game.controlledPlayer(0),s=game.score;$('homeflag').innerHTML=identity(home);$('awayflag').innerHTML=identity(away);$('homename').textContent=TEAMS[home].name.toUpperCase();$('awayname').textContent=TEAMS[away].name.toUpperCase();$('scoring').innerHTML=`${s[0]} <span>:</span> ${s[1]}`;$('weatherHud').textContent=game.weather.toUpperCase();let secs=Math.max(0,Math.ceil(game.matchSeconds-game.clock));$('timeHud').textContent=`${game.half===1?'1ST':'2ND'} • ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;if(p){const inPossession=game.ball.owner?.t===0;const ownBall=game.ball.owner===p;const goalkeeperHasBall=game.ball.owner?.t===0&&game.ball.owner?.keeper;for(const [key,text] of Object.entries(inPossession?{shoot:'SHOOT',pass:'PASS',dribble:'DRIBBLE',jump:'JUMP'}:{shoot:'SLIDE',pass:'TACKLE',dribble:'SWITCH',jump:'JUMP'})){const b=document.querySelector('[data-act="'+key+'"]');if(b&&b.textContent!==(goalkeeperHasBall&&key==='pass'?'CLEAR':text))b.textContent=goalkeeperHasBall&&key==='pass'?'CLEAR':text;}$('playerTag').textContent=`#${p.src.num} ${p.src.name.toUpperCase()}  ·  ${(p.src.superAbility?.type==='defence'&&!game.ball.owner?p.src.superAbility.name:p.src.shotName).toUpperCase()}  · LV${abilityLevel(p,(p.src.superAbility?.type==='defence'&&!game.ball.owner)?'defence':'shot')}  ·  ${(p.src.superAbility?.type==='defence'&&!game.ball.owner?(p.abilityCd||0):p.specialCd)>0?'SUPER RECHARGING':'SUPER READY'}  ·  ${moodLabel(p.morale)} ${Math.round(p.morale)}%`;const staminaBar=$('staminaFill');if(staminaBar)staminaBar.style.width=Math.round(100*(1-(p.fatigue||0)))+'%';const staminaText=$('staminaText');if(staminaText)staminaText.textContent=`STAMINA ${Math.round(100*(1-(p.fatigue||0)))}%`;const meter=$('powerFill');if(meter)meter.style.width=Math.max(0,Math.min(100,100*(p.charge||0)/1.2))+'%';const superLabel=$('specialMeter');if(superLabel){let defensive=p.src.superAbility?.type==='defence'&&!game.ball.owner;let abilityCooldown=defensive?(p.abilityCd||0):p.specialCd;superLabel.textContent=defensive?(abilityCooldown>0?'DEF CD '+abilityCooldown.toFixed(1)+'s':'★ DEF READY'):(abilityCooldown>0?'RECHARGE '+abilityCooldown.toFixed(1)+'s':'★ READY');superLabel.classList.toggle('charging',abilityCooldown>0)}}}
function showLeague(){home=0;mode='league';let list=[10,9,11,12];away=league.stage==='finals'?list[Math.min(league.playoff||0,3)]:(league.played%12)+1;
 page('WORLD LEAGUE','Win at least 16 games and accumulate 70 points to qualify for four championship finals.',`<div class="twoCol"><div class="panel"><div class="titleSmall">JAPAN • ${league.stage.toUpperCase()}</div><div class="tripleCol">${[['WINS',league.wins],['POINTS',league.points],['GAMES',league.played]].map(([a,b])=>`<div class="panel" style="text-align:center"><div class="badge">${a}</div><div style="font-size:34px;color:#ffdd76;font-weight:900">${b}</div></div>`).join('')}</div><p class="muted">Qualification: 16 wins / 70 points. Finals: ${league.playoff||0} / 4 victories.</p><div class="stat"><span>NEXT OPPONENT</span><strong>${TEAMS[away].name}</strong></div><div class="row" style="margin-top:15px">${league.stage==='champion'?'<strong>🏆 CUP WON — CHAMPIONS!</strong>':button('▶ NEXT MATCH','leagueKickoff','gold')}${button('RESET SEASON','clearLeague')}</div></div><div class="panel"><div class="titleSmall">MATCH HISTORY</div><div class="scroll"><table class="miniTable"><thead><tr><th>Opponent</th><th>Result</th></tr></thead><tbody>${(league.games||[]).slice(0,20).map(g=>`<tr><td>${escapeHTML(g.team)}</td><td>${g.a} - ${g.b}</td></tr>`).join('')||'<tr><td colspan="2">No results yet.</td></tr>'}</tbody></table></div></div></div>`)}
function showSquad(side=0,origin='home'){
 squadSide=side;squadContext=origin;
 const index=origin==='pause'?game.teamIds[side]:side===0?home:away;
 const team=TEAMS[index],players=origin==='pause'?game.rosters[side]:roster(index);
 const plan=origin==='pause'?safePlan(game.teamPlans[side],players,index):planFor(index);
 const order=['GK','DF','DF','MF','FW','FW'];
 const memberOptions=players.map((p,i)=>[i,`#${p.num} ${p.name} · ${p.role}`]);
 const fieldPlayerOptions=plan.lineup.map(i=>memberOptions[i]);
 const roleOptions=players.map((p,i)=>[i,`${plan.lineup.includes(i)?'●':'○'} #${p.num} ${p.name}`]);
 page('TEAM COMMAND CENTER',`${team.name} — edit formation, starting six, captain, set pieces and tactics ${origin==='pause'?'while the game is paused':'before kickoff'}.`,
 `<div class="squadHeader">${identity(index)}<strong>${escapeHTML(team.name)}</strong><span>${origin==='pause'?'LIVE TACTICS':'PREGAME PLAN'} · 6 ON FIELD / 6 BENCH</span></div><div class="twoCol"><div class="panel"><h3 class="titleSmall">FORMATION & LINEUP</h3>${field('FORMATION','formation',Object.keys(FORMATIONS).map(v=>[v,v]),plan.formation)}
 ${plan.lineup.map((id,i)=>`<div class="lineupRow"><strong>${order[i]}</strong>${choice('pos'+i,(i===0?memberOptions.filter(([j])=>players[j].role==='GK'):memberOptions.filter(([j])=>players[j].role!=='GK')),id)}<span class="pill">#${players[id]?.num||'?'}</span></div>`).join('')}
 <p class="muted">${origin==='pause'?`SUBSTITUTIONS: <b>${game.substitutionsUsed[side]} / ${game.maxSubstitutions}</b> used. Only ${game.maxSubstitutions} changes allowed; substituted-off players cannot return.`:'Before kickoff, choose any six starters. During play, use Pause to substitute up to three players.'} Substitutes enter with their own fitness; exhausted players lose speed, precision and tackling strength.</p>
 <h3 class="titleSmall">LEADERSHIP & SET PIECES</h3><div class="tacticsGrid">${[['captain','CAPTAIN'],['penalty','PENALTY KICKS'],['freeKick','FREE KICKS'],['corner','CORNERS']].map(([key,label])=>`<div>${field(label,'role_'+key,key==='captain'?fieldPlayerOptions:roleOptions,plan[key])}</div>`).join('')}</div>
 <h3 class="titleSmall">TEAM INSTRUCTIONS</h3><div class="tacticsGrid"><div>${field('ATTACKING STYLE','attackStyle',ATTACK_STYLES.map(v=>[v,v]),plan.attack)}</div><div>${field('DEFENSIVE STYLE','defenceStyle',DEFENCE_STYLES.map(v=>[v,v]),plan.defence)}</div></div>
 <p class="muted">Possession prioritizes passes; Direct pushes forward and shoots earlier. High Press closes down faster; Deep Block holds positions. Captain boosts team passing slightly. Penalty taker accuracy affects shootouts. Free-kick/corner roles are saved, but those restart mechanics are not yet playable.</p>
 <div class="row">${button('✓ SAVE TACTICS','saveSquad','gold')}${button('RESTORE DEFAULT','resetSquad')}${button('← BACK',origin==='setup'?'returnSetup':origin==='pause'?'returnPause':'home')}</div></div><div class="panel"><h3 class="titleSmall">12-PLAYER ROSTER</h3><div class="roster">${players.map((p,i)=>`<div class="rosterCard ${plan.lineup.includes(i)?'startingPlayer':''}"><div class="portrait">${p.role==='GK'?'🧤':'⚽'}</div><div><div class="rosterName">${plan.lineup.includes(i)?'● STARTING ':'○ BENCH '}#${p.num} ${escapeHTML(p.name)}</div><div class="rosterMeta">${p.role} · ${origin==='pause'?`FIT ${Math.round(100*(1-(game.fatigueLedger[side][p.id]??0)))}% · `:`CON ${p.condition??100}% · `}STA ${p.stamina} · DEF ${p.defence} · SPD ${p.speedRating} · AGI ${p.agility} · DRB ${p.dribbling}</div><div class="rosterMeta">SHOT ${p.shootPower}/${p.shootAccuracy} · HEAD ${p.heading} · PASS ${p.passing} · CROSS ${p.crossing} · STYLE ${escapeHTML(p.dribbleType||'sideStep')}</div><div class="rosterMeta">${p.role==='GK'?`GK JUMP ${p.gkJump} · GK SKILL ${p.gkSkill} · `:''}ABILITY ${escapeHTML(p.superAbility?.name||'NONE')} · SUPER SHOT LV${abilityLevel(p,'shot')} · DEF LV${p.superAbility?.type==='defence'?abilityLevel(p,'defence'):'—'} · GK LV${p.gkSuperAbility?abilityLevel(p,'keeper'):'—'}</div></div></div>`).join('')}</div></div></div>`,origin==='setup'?'returnSetup':origin==='pause'?'returnPause':'home');
}

function exportSave(){const keys=['customClubs','managerCareer','continentalRun','options','league','lineup','edits','teamPlans','controllerBindings','kitSelections'];const data={product:'Supermagic Football',version:'0.8.17.1',exportedAt:new Date().toISOString(),data:Object.fromEntries(keys.map(k=>[k,store.get(k,null)]))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Supermagic_Football_Save_'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function importSave(file){try{if(!file||file.size>5_000_000)throw Error('Save file missing or larger than 5MB');const parsed=JSON.parse(await file.text());if(!['Supermagic Football','Nekketsu Legends HD'].includes(parsed.product)||!parsed.data||typeof parsed.data!=='object')throw Error('Not a Supermagic Football save file');const allow=['customClubs','managerCareer','continentalRun','options','league','lineup','edits','teamPlans','controllerBindings','kitSelections'];if(!confirm('Importing this save will REPLACE local progress on this device. Continue?'))return;for(const key of allow){if(Object.hasOwn(parsed.data,key)&&parsed.data[key]!==null)store.put(key,parsed.data[key]);}alert('Save imported. Game will reload to apply the new progress.');location.reload()}catch(e){alert('Could not import save: '+e.message)}}

function showControls(){
 const bindings=input.getBindings(),codes=['KeyJ','KeyK','KeyI','KeyL','KeyQ','KeyE','KeyF','KeyG','KeyH','KeyU','KeyO','Space','Digit1','Digit2','Numpad0','Numpad1','Numpad2','Numpad3','NumpadDecimal','ControlRight','Comma','Period','Slash'];
 const names={Space:'SPACE',ControlRight:'RIGHT CTRL',NumpadDecimal:'NUMPAD DECIMAL'};
 const actions=['pass','shoot','dribble','jump'];
 const keyFields=(suffix,values)=>actions.map((a,i)=>field(a.toUpperCase(),'bindKey'+suffix+i,codes.map(k=>[k,names[k]||k.replace('Key','')]),values[i])).join('');
 const padFields=(suffix,values)=>actions.map((a,i)=>field(a.toUpperCase(),'bindPad'+suffix+i,Array.from({length:8},(_,n)=>[n,'BUTTON '+n+(n===0?' / A':n===1?' / B':n===2?' / X':n===3?' / Y':'')]),values[i])).join('');
 page('CONTROLLER MAPPING','Each player can remap four actions separately. The phone touchscreen stays a fixed four-button cross.',`<div class="twoCol"><div class="panel"><h3 class="titleSmall">PLAYER 1 · KEYBOARD</h3>${keyFields('',bindings.keyboard)}<h3 class="titleSmall">PLAYER 1 · GAMEPAD</h3>${padFields('',bindings.gamepad)}</div><div class="panel"><h3 class="titleSmall">PLAYER 2 · KEYBOARD</h3>${keyFields('2',bindings.keyboard2)}<h3 class="titleSmall">PLAYER 2 · GAMEPAD</h3>${padFields('2',bindings.gamepad2)}<p class="muted">Keys cannot overlap between players. Movement directions remain fixed. Connect two controllers for local versus.</p></div></div><div class="row">${button('SAVE BINDINGS','saveBindings','gold')}${button('RESTORE DEFAULTS','resetBindings')}${button('BACK TO SETTINGS','settings')}</div>`,'settings');
}
function showSettings(){page('SETTINGS','Stored in your browser; use the HD view for high-resolution vector graphics.',`<div class="twoCol"><div class="panel">${field('CPU DIFFICULTY','difficulty',aiChoices(),opt.difficulty)}${difficultyHint()}${field('MATCH PACE','gameSpeed',[[0.8,'Relaxed / 80%'],[1,'Normal / 100%'],[1.15,'Fast / 115%']],opt.gameSpeed||1)}${field('HALF LENGTH','settingsDuration',[60,120,180,300].map(v=>[v,v+' sec']),opt.halfSeconds)}${field('WEATHER','settingsWeather',WEATHER.map(v=>[v,v]),opt.weather)}${field('TERRAIN','settingsTerrain',TERRAIN.map(v=>[v,v]),opt.terrain)}${field('CONDITION','settingsCondition',CONDITIONS.map(v=>[v,v]),opt.condition)}</div><div class="panel">${field('CAMERA','camera',[['Follow','Follow the ball'],['Wide','Wide center view']],opt.camera)}${field('SHOW PLAYER NAMES','showNames',[['true','Yes'],['false','No']],String(opt.showNames))}${field('SOUND','sfx',[['true','On'],['false','Off']],String(opt.sfx))}<p class="muted">On Android, tap FULLSCREEN and rotate to landscape. On iPhone, use Safari Share → Add to Home Screen, then launch the installed game for the largest standalone display. Fullscreen and orientation locking are browser-dependent.</p><p class="muted">Browser support varies for Bluetooth gamepads. Connect the controller before opening a match and press one button to activate it.</p></div></div><div class="row" style="margin-top:15px">${button('✓ SAVE SETTINGS','saveSettings','gold')}${button('⬇ EXPORT ALL SAVES','exportSave')}${button('⬆ IMPORT SAVE','importSave')}${button('🎮 REMAP CONTROLS','controls')}<input id="saveImportFile" type="file" accept=".json,application/json" class="hidden" aria-label="Import saved game"/></div>`)}
function showHelp(){page('CONTROLS','PC, gamepads and landscape phone touch controls.',`<div class="twoCol"><div class="panel"><h3 class="titleSmall">PLAYER 1</h3>${[['Movement','WASD (arrows in 1P) / left stick'],['Shoot / Slide tackle','J / gamepad A; hold for strong shot; Jump + Shoot for an aerial shot; double Jump + Shoot for a Super Shot'],['Pass / Chase / tackle','K / gamepad B; hold for long pass, Jump + Pass for cross, on defense hold to chase'],['Legacy optional direct Super','L / gamepad LT — four-button combos will replace this'],['Jump / GK dive / Run','Space / gamepad Y; hold Jump and move for running; double Jump in air'] ,['TEAM JUMP','Hold Pass (K/B) + Jump (Space/Y) beside a teammate; Shoot for flip kick, Special near apex for a transforming combo shot'],['Dribble / Switch','I / gamepad X / touch DRIBBLE (double-tap for 10 personal tricks, Jump+Dribble for bicycle shot)'],['Switch','Tab / gamepad LB (legacy)'],['Sprint / Hyperdash','Hold Shift / gamepad RB while moving for 0.56 sec'],['Pause','P / Escape / Start']].map(([a,b])=>`<div class="stat"><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="panel"><h3 class="titleSmall">PLAYER 2</h3>${[['Movement','ARROWS / Numpad 8-4-5-6'],['Shoot','Comma / Numpad 1'],['Pass / Tackle','Period / Numpad 2'],['Dribble / Switch','Numpad Decimal / gamepad X'],['Super (legacy)','Slash / Numpad 3'],['Jump / Run','Right Ctrl / Numpad 0'],['Sprint / Hyperdash','Hold Right Shift while moving'],['Controller','Second gamepad; actions independently remappable in Settings']].map(([a,b])=>`<div class="stat"><strong>${a}</strong><span>${b}</span></div>`).join('')}<p class="muted">During penalties, steer the ball before shooting; DRIBBLE feints; goalkeepers steer and tap Jump for a timed dive. Player 1 and Player 2 keyboard/gamepad mappings are in Settings → Remap Controls. The phone has exactly four cross-arranged actions: Pass, Shoot, Dribble, Jump. Defensive Dribble switches players; defensive Shoot slides; short Pass tackles and long Pass chases. Legacy Super shortcut remains available for compatibility until full controller remapping. In midair press Shoot near a loose airborne ball for a header. On defense press Jump near your goal to request a GK dive. Rare supernatural saves still use Special. Defending: double Jump then Shoot for an aerial bicycle kick; Jump+Shoot makes an ordinary GK dive when possible. Aerial combination: hold Pass and tap Jump by a grounded teammate; Shoot for flip kick, Special at the apex for a transforming combo shot. Exact historical timing remains unverified.</p></div></div>`)}
function showEditor(){page('PLAYER DATA EDITOR','Edit your own 12-player team roster in JSON. Every player can change shot and stats.',`<div class="twoCol"><div class="panel">${field('SELECT NATIONAL TEAM','editTeam',nations(),home)}<label class="fieldLabel">TEAM PLAYER DEFINITIONS</label><textarea id="jsonRoster" style="width:100%;height:280px;padding:12px;background:#061625;color:#c5eaff;border:1px solid #90bbcb;border-radius:9px;touch-action:pan-y" spellcheck="false">${escapeHTML(JSON.stringify(roster(home),null,2))}</textarea><div class="row" style="margin-top:12px">${button('✓ APPLY','importRoster','gold')}${button('⬇ EXPORT','exportRoster')}</div></div><div class="panel"><h3 class="titleSmall">EDITABLE ENGINE</h3><p class="muted">Individual player data includes the fourteen 1–100 ratings: stamina, strength, aggression, defence, speedRating, agility, dribbling, shootPower, shootAccuracy, heading, passing, crossing, gkJump, gkSkill. dribbleType selects one of ten gameplay-distinct tricks. superAbility and gkSuperAbility hold optional unique move definitions. superShotLevel, superDefenceLevel and gkSuperLevel can explicitly override arcade strength tiers (1–5); top tiers are reserved for a small editorial star shortlist. Existing legacy power, shoot, defense, speed are retained for compatibility. The same engine is intended to support new clubs, abilities and growth later.</p><p class="muted">Available super shots: ${Object.keys(SHOTS).join(', ')}.</p><p class="muted">The source code is included in the ZIP for extensions. Online play, the career economy and custom competition designer are future work—not currently playable.</p></div></div>`)}

